#include <algorithm>
#include <fstream>
using namespace std;
int main() {
    ifstream in("mixmilk.in");
    ofstream out("mixmilk.out");
    long long capacity[3], milk[3];
    for (int i = 0; i < 3; ++i) in >> capacity[i] >> milk[i];
    for (int operation = 0; operation < 100; ++operation) {
        int source = operation % 3, destination = (source + 1) % 3;
        long long moved = min(milk[source], capacity[destination] - milk[destination]);
        milk[source] -= moved;
        milk[destination] += moved;
    }
    for (long long amount : milk) out << amount << '\n';
}
