#include <algorithm>
#include <fstream>
using namespace std;
int main() {
    ifstream in("blist.in");
    ofstream out("blist.out");
    int n, changes[1002] = {};
    in >> n;
    for (int i = 0; i < n; ++i) {
        int start, finish, buckets;
        in >> start >> finish >> buckets;
        changes[start] += buckets;
        changes[finish] -= buckets;
    }
    int current = 0, answer = 0;
    for (int time = 1; time <= 1000; ++time) {
        current += changes[time];
        answer = max(answer, current);
    }
    out << answer << '\n';
}
