#include <fstream>
#include <set>
#include <vector>
using namespace std;
set<int> readings;
void search(int day, vector<int> left, vector<int> right, int milk) {
    if (day == 4) {
        readings.insert(milk);
        return;
    }
    if (day % 2 == 0) {
        for (int i = 0; i < static_cast<int>(left.size()); ++i) {
            vector<int> next_left = left, next_right = right;
            int bucket = next_left[i];
            next_left.erase(next_left.begin() + i);
            next_right.push_back(bucket);
            search(day + 1, next_left, next_right, milk - bucket);
        }
    } else {
        for (int i = 0; i < static_cast<int>(right.size()); ++i) {
            vector<int> next_left = left, next_right = right;
            int bucket = next_right[i];
            next_right.erase(next_right.begin() + i);
            next_left.push_back(bucket);
            search(day + 1, next_left, next_right, milk + bucket);
        }
    }
}
int main() {
    ifstream in("backforth.in");
    ofstream out("backforth.out");
    vector<int> first(10), second(10);
    for (int &bucket : first) in >> bucket;
    for (int &bucket : second) in >> bucket;
    search(0, first, second, 1000);
    out << readings.size() << '\n';
}
